script:
(function () {
  'use strict';
  // ===== Tax figures: tax year 2026 =====
  // Ordinary brackets and capital gains breakpoints: IRS Rev. Proc. 2025-32, sections 4.01 and 4.03
  //   (as amended by P.L. 119-21). Later years use the same 2026 figures (no inflation indexing).
  // Capital loss limit $3,000 ($1,500 separate): IRC 1211(b). Net investment income tax 3.8%:
  //   IRC 1411; NUA itself is excluded, appreciation after the distribution is included
  //   (Treas. Reg. 1.1411-8(b)(4)).
  // 10% additional tax on early distributions: IRC 72(t); applies to the taxable cost basis, not
  //   to the NUA; exception for leaving the employer in or after the year you turn 55 (plan
  //   distributions only, not IRAs) - IRS Pub. 575.
  // NUA rules: IRS Pub. 575 "Distributions of employer securities" - with a lump-sum distribution
  //   the NUA is not taxed until the shares are sold, then is long-term gain whatever the holding
  //   period; later growth is long- or short-term depending on time held after the distribution.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj: [24800, 100800, 211400, 403550, 512450, 768700],
    hoh: [17700, 67450, 105700, 201750, 256200, 640600],
    mfs: [12400, 50400, 105700, 201775, 256225, 384350]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850] };
  var LOSS_LIMIT = { single: 3000, mfj: 3000, hoh: 3000, mfs: 1500 };
  var NIIT_RATE = 0.038, EARLY_PENALTY = 0.10;
  // ======================================
  // Method. Stock value V, cost basis B, growth g a year, first sale after W years, shares sold
  // (or IRA withdrawn) in N equal yearly parts, each part 1/N of the shares, worth V/N x (1+g)^s.
  //   NUA route: year 0 - basis B is ordinary income (+10% if under 59 1/2 without the age-55
  //     exception). Each sale - NUA part (V - B)/N is long-term gain; growth above V/N is long-term
  //     (short-term only for a sale in year 0, where it is zero).
  //   IRA route: every withdrawal is ordinary income (+10% if under 59 1/2 at that time).
  //   Federal tax each year is incremental over that year's other taxable income (this year's
  //   figure for year 0, the "later" figure afterwards), with gains stacked at 0/15/20%. State tax
  //   is a flat rate on the income. "Today's dollars" discounts each year's tax at the growth
  //   rate, so tax paid now weighs more than the same tax paid later.
  // Verified (Node, scratch tests, against hand calculations): single, $80,000 taxable income now,
  //   $60,000 later, $300,000 stock with a $60,000 basis, age 60, 0% growth, no state tax, all sold
  //   (or withdrawn) in year 1: NUA route - tax now $13,886 (25,700 x 22% + 34,300 x 24%), then
  //   $240,000 long-term at 15% = $36,000, total $49,886; IRA route - $300,000 on top of $60,000 =
  //   $94,769.25 - $7,912 = $86,857; NUA saves $36,971. Age 50: + $6,000 (10% of basis) now and
  //   + $30,000 on the IRA withdrawal; left employer at 55+: basis penalty waived, IRA one kept.
  //   5% state: + $3,000 now, + $12,000 / + $15,000 at sale. 10% growth: $330,000 sold, $270,000
  //   long-term = $40,500 + NIIT 3.8% x $30,000 = $1,140; today's dollars 13,886 + 41,640 / 1.1 =
  //   $51,741. Price falls 20%: gain $180,000 x 15% = $27,000. Sale in year 0: $49,886 in one year.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }

  function ordinaryTax(income, status) {
    var limits = BRACKETS[status], tax = 0, lower = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] : Infinity;
      if (income > lower) tax += (Math.min(income, upper) - lower) * RATES[i];
      lower = upper;
    }
    return tax;
  }

  function federal(status, ordinary, st, lt) {
    var net = st + lt, pref = 0, ordGain = 0, deduction = 0;
    if (net >= 0) { pref = lt > 0 ? Math.min(lt, net) : 0; ordGain = net - pref; }
    else deduction = Math.min(-net, LOSS_LIMIT[status]);
    var taxable = Math.max(0, ordinary + ordGain + pref - deduction);
    var gains = Math.min(pref, taxable), base = taxable - gains, b = CG_BREAKS[status];
    var mid = Math.max(0, Math.min(taxable, b[1]) - Math.max(base, b[0]));
    var top = Math.max(0, taxable - Math.max(base, b[1]));
    return Math.min(ordinaryTax(base, status) + 0.15 * mid + 0.20 * top, ordinaryTax(taxable, status));
  }

  function compare(o) {
    var last = o.wait + o.parts - 1, rows = [];
    var nua = { tax: 0, pv: 0, cash: 0 }, ira = { tax: 0, pv: 0, cash: 0 };
    var upfront = { fed: 0, state: 0, penalty: 0 };
    for (var s = 0; s <= last; s++) {
      var income = s === 0 ? o.incomeNow : o.incomeLater;
      var selling = s >= o.wait, proceeds = 0, ordN = 0, st = 0, lt = 0, extraGain = 0, penN = 0;
      if (s === 0) {
        ordN = o.basis;
        if (o.age < 59.5 && !o.sep55) penN = EARLY_PENALTY * o.basis;
      }
      if (selling) {
        var part = o.value / o.parts;
        proceeds = part * Math.pow(1 + o.growth, s);
        var nuaPart = (o.value - o.basis) / o.parts;
        extraGain = proceeds - part;
        if (extraGain >= 0) { lt += nuaPart; if (s >= 1) lt += extraGain; else st += extraGain; }
        else lt += proceeds - o.basis / o.parts;
      }
      var base = federal(o.status, income, 0, 0);
      var fedN = federal(o.status, income + ordN, st, lt) - base;
      var stateN = o.state * Math.max(0, ordN + st + lt);
      var niitN = o.niit ? NIIT_RATE * Math.max(0, extraGain) : 0;
      var taxN = fedN + stateN + niitN + penN;
      if (s === 0) {
        var fedBasis = federal(o.status, income + o.basis, 0, 0) - base;
        upfront = { fed: fedBasis, state: o.state * o.basis, penalty: penN };
      }
      var fedI = selling ? federal(o.status, income + proceeds, 0, 0) - base : 0;
      var penI = selling && o.age + s < 59.5 ? EARLY_PENALTY * proceeds : 0;
      var taxI = fedI + o.state * proceeds + penI;
      var disc = Math.pow(1 + o.growth, s);
      nua.tax += taxN; nua.pv += taxN / disc; nua.cash += proceeds - taxN;
      ira.tax += taxI; ira.pv += taxI / disc; ira.cash += proceeds - taxI;
      if (s === 0 || selling) rows.push({ year: s, proceeds: proceeds, nua: taxN, ira: taxI });
    }
    return { nua: nua, ira: ira, upfront: upfront, rows: rows };
  }

  function update() {
    var o = {
      value: num('nuValue'), basis: num('nuBasis'), age: num('nuAge'), sep55: document.getElementById('nuSep55').checked,
      status: document.getElementById('nuStatus').value, incomeNow: num('nuIncome'), incomeLater: num('nuLaterIncome'),
      state: num('nuState') / 100, growth: num('nuGrowth') / 100, wait: Math.round(num('nuWait')),
      parts: Math.round(num('nuParts')), niit: document.getElementById('nuNiit').checked
    };
    var error = document.getElementById('nuError'), msg = '';
    if ([o.value, o.basis, o.age, o.incomeNow, o.incomeLater, o.state, o.growth, o.wait, o.parts].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.value <= 0) msg = 'Enter the value of your company stock.';
    else if (o.basis < 0) msg = 'The cost basis cannot be negative.';
    else if (o.basis >= o.value) msg = 'The cost basis is at or above the stock’s value, so there is no net unrealized appreciation to benefit from.';
    else if (o.age < 18 || o.age > 100) msg = 'Enter an age from 18 to 100.';
    else if (o.incomeNow < 0 || o.incomeLater < 0) msg = 'Other taxable income cannot be negative.';
    else if (o.state < 0 || o.state > 0.15) msg = 'Enter a state tax rate from 0% to 15%.';
    else if (o.growth < -0.2 || o.growth > 0.2) msg = 'Enter a growth rate from -20% to 20%.';
    else if (o.wait < 0 || o.wait > 40) msg = 'Enter from 0 to 40 years before the first sale.';
    else if (o.parts < 1 || o.parts > 30) msg = 'Spread the sales over 1 to 30 years.';
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var r = compare(o), diff = r.ira.pv - r.nua.pv;
    set('nuAdvantageLabel', diff >= 0 ? 'NUA saves you (today’s dollars)' : 'Rolling over saves you (today’s dollars)');
    set('nuAdvantage', money.format(Math.abs(diff)));
    set('nuNuaPv', money.format(r.nua.pv));
    set('nuIraPv', money.format(r.ira.pv));
    set('nuNuaAmount', money.format(o.value - o.basis));
    set('nuUpfront', money.format(r.upfront.fed + r.upfront.state + r.upfront.penalty));
    set('nuUpfrontFed', money.format(r.upfront.fed));
    set('nuUpfrontState', money.format(r.upfront.state));
    set('nuUpfrontPenalty', money.format(r.upfront.penalty));
    set('nuNuaTotal', money.format(r.nua.tax));
    set('nuIraTotal', money.format(r.ira.tax));
    set('nuNuaCash', money.format(r.nua.cash));
    set('nuIraCash', money.format(r.ira.cash));
    var note = document.getElementById('nuNote');
    var early = o.age < 59.5;
    note.hidden = !early;
    note.textContent = early ? (o.sep55 ? 'The 10% early distribution tax is waived on the plan distribution because you left this employer in or after the year you turned 55. IRA withdrawals before 59½ would still owe it.' :
      'You are under 59½, so the 10% early distribution tax applies to the taxable cost basis now (and to IRA withdrawals made before 59½).') : '';

    document.getElementById('nuYearBody').innerHTML = r.rows.map(function (row) {
      return '<tr><td>' + (row.year === 0 ? 'Now (' + TAX_YEAR + ')' : 'Year ' + row.year) + '</td><td>' + money.format(row.proceeds) +
        '</td><td>' + money.format(row.nua) + '</td><td>' + money.format(row.ira) + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('nuForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
